API Gateway / BFF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway / BFF container

Container_Boundary(api_gateway_bff, "API Gateway / BFF") {
    Component(api_gateway_edge_router, "API Gateway & Edge Router", "Go / Envoy", "Handles edge routing, ingress traffic, rate limiting, and SSL termination.")
    Component(bff_routing_controller, "BFF Routing Controller", "Go", "Orchestrates and routes incoming client requests to respective backend microservices via gRPC over mTLS.")
}

Rel(api_gateway_edge_router, bff_routing_controller, "Forwards validated client requests")

@enduml
